"""lint_check: flag iverilog-hostile patterns before simulation.

Written by the Builder coach in round 3, after 6 train failures traced
back to the same three mistakes.
"""
import re

CLOCKED = re.compile(r"always\s*@\s*\(\s*(?:posedge|negedge)[^)]*\)(.*?)\bend\b", re.S)
SV_ONLY = ("always_ff", "always_comb", "unique case", "priority case")


def run(spec, verilog, ports):
    findings = []
    if "module TopModule" not in verilog:
        findings.append("module must be named TopModule")

    # blocking '=' inside a clocked block collapses register chains
    for block in CLOCKED.finditer(verilog):
        if re.search(r"[^<>=!]=[^=]", block.group(1)):
            findings.append("blocking '=' in clocked always block; use '<='")

    for kw in SV_ONLY:
        if kw in verilog:
            findings.append(f"'{kw}' is SystemVerilog; iverilog may reject it")

    for port in ports:
        if not re.search(rf"\b{port['name']}\b", verilog):
            findings.append(f"port '{port['name']}' from the spec is not declared")

    return {"fired": bool(findings), "findings": findings}
